class Solution {public:
 long long maxGCDScore(vector<int>& nums,int k){
  long long ans=0;int n=nums.size();
  for(int i=0;i<n;++i){int g=0,minTwos=100,cnt=0;
   for(int j=i;j<n;++j){int x=nums[j];g=__gcd(g,x);int t=__builtin_ctz((unsigned)x);
    if(t<minTwos){minTwos=t;cnt=1;}else if(t==minTwos)++cnt;
    ans=max(ans,1LL*(j-i+1)*g*(cnt<=k?2:1));
   }
  }return ans;
 }
};
